        {agents && agents.length > 0 ? (
          <div className="flex flex-col gap-0.5 border-t border-border/60 pt-1.5 mt-0.5">
            <div className="px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/60">
              AGENTS
            </div>
            {agents.map((agent) => {
