import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Globe, Pin, TerminalSquare, X } from "lucide-react";
import type { KeyboardEvent, MouseEvent, PointerEvent } from "react";

import { resolveActivityIndicator, type ActivitySummary } from "../../lib/activity";
import { cn } from "../../lib/cn";
import type { WorkspaceTab } from "../../lib/types";
import { StatusDot } from "../ui/StatusDot";

type SortableTabProps = {
  tab: WorkspaceTab;
  groupId: string;
  index: number;
  active: boolean;
  unread: boolean;
  activity?: ActivitySummary;
  isRenaming: boolean;
  renameValue: string;
  onRenameValueChange: (value: string) => void;
  onCommitRename: (tabId: string) => void;
  onCancelRename: () => void;
  onActivate: (tabId: string) => void;
  onClose: (tabId: string) => void;
  onContextMenu: (event: MouseEvent, tab: WorkspaceTab) => void;
};

export function SortableTab({
  tab,
  groupId,
  index,
  active,
  unread,
  activity,
  isRenaming,
  renameValue,
  onRenameValueChange,
  onCommitRename,
  onCancelRename,
  onActivate,
  onClose,
  onContextMenu,
}: SortableTabProps) {
  const sortable = useSortable({
    id: `tab:${tab.id}`,
    disabled: isRenaming,
    data: { type: "tab", tabId: tab.id, groupId, index },
  });
  const resolvedActivity = tab.kind === "browser" ? null : resolveActivityIndicator(activity);
  const activityIndicator = unread && (resolvedActivity === null || resolvedActivity === "done") ? "unread" : resolvedActivity;
  const isPinned = Boolean(tab.pinned);

  const style = {
    transform: CSS.Transform.toString(sortable.transform),
    transition: sortable.transition,
  };

  const stopPointer = (event: PointerEvent) => event.stopPropagation();

  return (
    <div
      ref={sortable.setNodeRef}
      {...sortable.attributes}
      {...sortable.listeners}
      role="tab"
      aria-selected={active}
      tabIndex={active ? 0 : -1}
      data-tab-dnd-id={tab.id}
      data-tab-group-id={groupId}
      data-tab-index={index}
      data-dnd-type="tab"
      draggable={false}
      onContextMenu={(event) => onContextMenu(event, tab)}
      onClick={() => onActivate(tab.id)}
      onKeyDown={(event: KeyboardEvent) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onActivate(tab.id);
        }
      }}
      style={style}
      className={cn(
        "no-drag group relative flex min-w-tab max-w-tab cursor-pointer touch-none items-center gap-1.5 border-r border-border px-2 text-[12px] transition-colors outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring",
        active ? "bg-terminal text-foreground" : "bg-card text-muted-foreground hover:bg-accent/45 hover:text-foreground",
        sortable.isDragging && "z-40 opacity-30",
      )}
    >
      {tab.kind === "browser" ? (
            <Globe className="size-3 shrink-0 text-primary" />
      ) : activityIndicator ? (
        <span
          data-testid={activityIndicator === "unread" ? "tab-unread-dot" : `tab-${activityIndicator}-indicator`}
          aria-label={`Agent ${activityIndicator}`}
          className="inline-flex size-3 shrink-0 items-center justify-center"
        >
          <StatusDot state={activityIndicator} />
        </span>
      ) : (
        <TerminalSquare className="size-3 shrink-0" />
      )}

      {isRenaming ? (
        <input
          type="text"
          value={renameValue}
          autoFocus
          data-tab-rename-input="true"
          onClick={(event) => event.stopPropagation()}
          onPointerDown={stopPointer}
          onChange={(event) => onRenameValueChange(event.target.value)}
          onBlur={() => onCommitRename(tab.id)}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === "Enter") {
              event.preventDefault();
              event.currentTarget.blur();
            } else if (event.key === "Escape") {
              event.preventDefault();
              onCancelRename();
              event.currentTarget.blur();
            }
          }}
          className="min-w-0 flex-1 rounded border border-ring bg-background px-1 py-0.5 text-xs text-foreground outline-none"
        />
      ) : (
        <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
      )}

      {isPinned ? <Pin className="size-2.5 shrink-0 text-muted-foreground/80" aria-label="Pinned tab" /> : null}

      {!isPinned ? (
        <span
          role="button"
          tabIndex={0}
          aria-label={`Close ${tab.label}`}
          onPointerDown={stopPointer}
          onClick={(event) => {
            event.stopPropagation();
            onClose(tab.id);
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              event.stopPropagation();
              onClose(tab.id);
            }
          }}
          className="no-drag rounded p-0.5 text-muted-foreground opacity-0 hover:bg-muted hover:text-foreground group-hover:opacity-100 focus:opacity-100"
        >
          <X className="size-3" />
        </span>
      ) : null}

      {active ? (
        <span data-testid="tab-active-indicator" className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-foreground" />
      ) : null}
    </div>
  );
}

import { useDroppable } from "@dnd-kit/core";
import type { ReactNode } from "react";

import { cn } from "../../lib/cn";
import type { TabDropEdge } from "./tabDragTypes";

type TabGroupDropSurfaceProps = {
  groupId: string;
  children: ReactNode;
};

export function TabGroupDropSurface({ groupId, children }: TabGroupDropSurfaceProps) {
  const body = useDroppable({
    id: `group-body:${groupId}`,
    data: { type: "group-body", groupId },
  });

  return (
    <div
      ref={body.setNodeRef}
      data-tab-group-body-id={groupId}
      data-dnd-type="group-body"
      className="relative min-h-0 flex-1 overflow-hidden bg-terminal"
    >
      {children}
      <TabGroupEdgeDropZone groupId={groupId} edge="left" />
      <TabGroupEdgeDropZone groupId={groupId} edge="right" />
      <TabGroupEdgeDropZone groupId={groupId} edge="top" />
      <TabGroupEdgeDropZone groupId={groupId} edge="bottom" />
    </div>
  );
}

function TabGroupEdgeDropZone({ groupId, edge }: { groupId: string; edge: TabDropEdge }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `group-edge:${groupId}:${edge}`,
    data: { type: "group-edge", groupId, edge },
  });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid="tab-group-edge-drop-zone"
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-dnd-type="group-edge"
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edge === "left" && "inset-y-0 left-0 w-[20%]",
        edge === "right" && "inset-y-0 right-0 w-[20%]",
        edge === "top" && "left-[20%] right-[20%] top-0 h-[20%]",
        edge === "bottom" && "bottom-0 left-[20%] right-[20%] h-[20%]",
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm">
          New split
        </span>
      ) : null}
    </div>
  );
}

import type { TabDropEdge } from "./tabDragTypes";
import { SplitEdgeDropZone } from "./SplitEdgeDropZone";

const EDGES: TabDropEdge[] = ["left", "right", "top", "bottom"];

type PaneEdgeDropZonesProps = {
  tabId: string;
  leafId: string;
};

export function PaneEdgeDropZones({ tabId, leafId }: PaneEdgeDropZonesProps) {
  return (
    <>
      {EDGES.map((edge) => (
        <SplitEdgeDropZone
          key={edge}
          id={`pane-edge:${tabId}:${leafId}:${edge}`}
          data={{ type: "pane-edge", tabId, leafId, edge }}
          edge={edge}
          testId="pane-edge-drop-zone"
          tabId={tabId}
          leafId={leafId}
        />
      ))}
    </>
  );
}

import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid={testId}
      data-split-edge-drop-zone="true"
      data-dnd-type={data.type}
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-tab-id={tabId}
      data-leaf-id={leafId}
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edgeHitTargetClass(edge),
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span
          data-testid="split-edge-drop-feedback"
          className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
        >
          New split
        </span>
      ) : null}
    </div>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

import type { ButtonHTMLAttributes, ReactNode } from "react";

import { cn } from "../../lib/cn";

type IconButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  label: string;
  children: ReactNode;
  size?: "sm" | "md";
};

export function IconButton({
  label,
  children,
  className,
  size = "md",
  type = "button",
  ...props
}: IconButtonProps) {
  return (
    <button
      type={type}
      aria-label={label}
      title={label}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors",
        "hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
        "disabled:pointer-events-none disabled:opacity-40",
        size === "sm" ? "size-6" : "size-7",
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
}

import type { ReactNode } from "react";

import { cn } from "../../lib/cn";

type SectionHeaderProps = {
  title: string;
  count?: number;
  actions?: ReactNode;
  className?: string;
};

export function SectionHeader({ title, count, actions, className }: SectionHeaderProps) {
  return (
    <div className={cn("flex h-8 items-center justify-between gap-2 px-2", className)}>
      <div className="flex min-w-0 items-center gap-1.5 pl-2 text-xs font-semibold text-muted-foreground/80">
        <span className="truncate">{title}</span>
        {count !== undefined ? (
          <span className="rounded-full bg-sidebar-accent px-1.5 py-0.5 text-[10px] leading-none text-muted-foreground">
            {count}
          </span>
        ) : null}
      </div>
      {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
    </div>
  );
}

import { LoaderCircle } from "lucide-react";

import { cn } from "../../lib/cn";
import type { TerminalActivityState } from "../../lib/activity";
import type { AgentState } from "../../lib/types";

export type StatusDotState = AgentState | TerminalActivityState | "unread";

type StatusDotProps = {
  state: StatusDotState;
  className?: string;
};

export function StatusDot({ state, className }: StatusDotProps) {
  if (state === "working") {
    return (
      <LoaderCircle
        aria-hidden="true"
        data-status-state="working"
        className={cn("size-3 shrink-0 animate-spin text-status-working motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "starting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="starting"
        className={cn("size-2 shrink-0 animate-pulse rounded-full bg-status-warning motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "waiting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="waiting"
        className={cn("size-2 shrink-0 rounded-full bg-status-warning ring-2 ring-status-warning/20", className)}
      />
    );
  }

  if (state === "unread") {
    return (
      <span
        aria-hidden="true"
        data-status-state="unread"
        className={cn("size-2 shrink-0 rounded-full bg-primary", className)}
      />
    );
  }

  if (state === "done" || state === "exited") {
    return (
      <span
        aria-hidden="true"
        data-status-state="done"
        className={cn("size-2 shrink-0 rounded-full bg-status-success", className)}
      />
    );
  }

  return (
    <span
      aria-hidden="true"
      data-status-state="failed"
      className={cn("size-2 shrink-0 rounded-full bg-destructive", className)}
    />
  );
}

